  function onLayerDragOver(e:DragEvent,id:string){if(!dragLayerId)return;e.preventDefault();e.stopPropagation();e.dataTransfer!.dropEffect="move";dropLayerId=id;}
  function onLayerDrop(e:DragEvent,targetId:string){e.preventDefault();e.stopPropagation();const fromId=dragLayerId;dragLayerId=null;dropLayerId=null;if(!fromId||fromId===targetId)return;const layers=[...doc.layers],from=layers.findIndex(l=>l.id===fromId),to=layers.findIndex(l=>l.id===targetId);if(from<0||to<0)return;const [item]=layers.splice(from,1);layers.splice(to,0,item);doc={...doc,layers};renderDocument();queueSave();}
  function onLayerDragEnd(){dragLayerId=null;dropLayerId=null;}
  function setBleed(side:keyof typeof doc.spec.bleed,event:Event){doc.spec.bleed[side]=Number((event.target as HTMLInputElement).value);updateSpec();}
  function setEffectParam(effect:NonNullable<typeof active>["effects"][number],key:string,event:Event){const input=event.target as HTMLInputElement;effect.params[key]=input.type==="checkbox"?input.checked:input.type==="number"||input.type==="range"?Number(input.value):input.value;if(effect.type==="halftone"&&effect.params.linkSpacing&&(key==="spacingX"||key==="spacingY")){const n=Number(effect.params[key]);effect.params.spacingX=n;effect.params.spacingY=n;}doc={...doc,layers:[...doc.layers]};applyEffects();}
  function toggleHalftoneLink(effect:NonNullable<typeof active>["effects"][number]){const on=!effect.params.linkSpacing;effect.params.linkSpacing=on;if(on)effect.params.spacingY=effect.params.spacingX;doc={...doc,layers:[...doc.layers]};applyEffects();}
  function setLayerScale(axis:"scaleX"|"scaleY",event:Event){if(!active)return;active.transform[axis]=Math.max(.01,Number((event.target as HTMLInputElement).value)/100);doc={...doc,layers:[...doc.layers]};renderDocument();queueSave();}
  function openSettings(){settingsOriginal=structuredClone(doc.spec);showSettings=true;}
  async function cancelSettings(){if(settingsOriginal)doc={...doc,spec:settingsOriginal};showSettings=false;await tick();setupCanvas();}
  async function ingestImage(file:File){if(!file.type.startsWith("image/"))return null;const image=await createImageBitmap(file);const bytes=await file.arrayBuffer(),hash=await crypto.subtle.digest("SHA-256",bytes),id=uid();const checksum=[...new Uint8Array(hash)].map(x=>x.toString(16).padStart(2,"0")).join("");const asset:SourceAsset={id,name:file.name,mime:file.type,width:image.width,height:image.height,checksum,bytes:file};assets.set(id,asset);return {image,asset};}
  function drawImport(layer:ArtLayer,image:ImageBitmap,clear:boolean){const scale=fitImportScale(image.width,image.height,px.width,px.height),b=bufferFor(layer),c=b.getContext("2d")!;if(clear)c.clearRect(0,0,b.width,b.height);c.drawImage(image,(px.width-image.width*scale)/2,(px.height-image.height*scale)/2,image.width*scale,image.height*scale);layer.bitmap=b.toDataURL();}
  async function importImageFile(file:File){const loaded=await ingestImage(file);if(!loaded)return;const layer=newLayer(file.name);layer.type="image";layer.assetId=loaded.asset.id;doc={...doc,layers:[layer,...doc.layers],activeLayerId:layer.id};drawImport(layer,loaded.image,false);commit();}
  async function replaceLayerContent(file:File){if(!active)return;const loaded=await ingestImage(file);if(!loaded)return;const owner=ownerOf(active),oldAssetId=owner.assetId;checkpointOwner();owner.type="image";owner.assetId=loaded.asset.id;drawImport(owner,loaded.image,true);gcAsset(oldAssetId);commit();}
  async function importImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await importImageFile(file);input.value="";}
  async function onReplaceImage(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(file)await replaceLayerContent(file);input.value="";}
  function onFileDragOver(e:DragEvent){if(!e.dataTransfer?.types.includes("Files"))return;e.preventDefault();e.dataTransfer.dropEffect="copy";fileDrop=true;}
  function onFileDragLeave(e:DragEvent){const next=e.relatedTarget as Node|null;if(!next||!(e.currentTarget as Node).contains(next))fileDrop=false;}
  async function onFileDrop(e:DragEvent){fileDrop=false;const files=[...e.dataTransfer?.files??[]].filter(f=>f.type.startsWith("image/"));if(!files.length)return;e.preventDefault();for(const file of files.reverse())await importImageFile(file);}
  function addEffect(type:EffectType){if(!active)return;active.effects=[...active.effects,createEffect(type)];doc={...doc,layers:[...doc.layers]};applyEffects();}
  async function applyEffects(){renderDocument();queueSave();}
  function moveEffect(index:number,delta:number){if(!active)return;const n=index+delta;if(n<0||n>=active.effects.length)return;[active.effects[index],active.effects[n]]=[active.effects[n],active.effects[index]];active.effects=[...active.effects];doc={...doc,layers:[...doc.layers]};applyEffects();}
  function removeEffect(index:number){if(!active)return;active.effects=active.effects.filter((_,i)=>i!==index);doc={...doc,layers:[...doc.layers]};applyEffects();}
  function toggleTheme(){const root=document.documentElement,next=root.dataset.theme==="xianii"?"xianii-light":"xianii";root.dataset.theme=next;localStorage.setItem("theme",next);}
  async function toggleLocale(){locale=locale==="zh-CN"?"en":"zh-CN";doc={...doc,locale};localStorage.setItem("locale",locale);await tick();setupCanvas();}
  function fresh(){doc=newDocument(locale);assets=new Map();layerBuffers.clear();boxCache.clear();history=[];future=[];dialog=null;view={x:0,y:0};setTimeout(setupCanvas);queueSave();}
  async function saveFile(){download(await exportProject(doc,assets),`${doc.name||"Untitled"}.artmaker`);}
  async function openProject(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;const loaded=await importProject(file);doc=loaded.document;assets=new Map(loaded.assets.map(a=>[a.id,a]));locale=doc.locale;await tick();setupCanvas();await hydrateLayers();queueSave();}
  async function exportPng(){renderDocument();const blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(v=>v?resolve(v):reject(),"image/png"));download(blob,`${doc.name||"ArtMaker"}-${px.width}x${px.height}.png`);}
  async function updateSpec(){doc={...doc,spec:{...doc.spec,bleed:{...doc.spec.bleed}}};await tick();setupCanvas();queueSave();}
  const zoomLevels=[.1,.125,.16,.2,.25,.33,.4,.5,.67,.8,1,2,3,4];
  async function setZoom(next:number,clientX?:number,clientY?:number){const old=zoom,rect=stage.getBoundingClientRect(),x=(clientX??rect.left+rect.width/2)-rect.left,y=(clientY??rect.top+rect.height/2)-rect.top,cx=rect.width/2,cy=rect.height/2,docX=(x-cx-view.x)/old,docY=(y-cy-view.y)/old;zoom=next;await tick();view=clampView(x-cx-docX*zoom,y-cy-docY*zoom);}
  function wheel(e:WheelEvent){e.preventDefault();if(e.shiftKey){size=Math.max(1,Math.min(500,size+(e.deltaY<0?1:-1)));return}const index=zoomLevels.indexOf(zoom),next=zoomLevels[Math.max(0,Math.min(zoomLevels.length-1,index+(e.deltaY<0?1:-1)))];if(next!==zoom)setZoom(next,e.clientX,e.clientY);}
  onMount(async()=>{locale=(localStorage.getItem("locale") as typeof locale)||((navigator.language.startsWith("zh"))?"zh-CN":"en");const saved=await loadAutosave();if(saved){doc=saved.document;assets=new Map(saved.assets.map(a=>[a.id,a]));locale=doc.locale;status=t("restore");}setupCanvas();await hydrateLayers();});
</script>

<svelte:window onkeydown={(e)=>{if(e.key==="Escape"){pickingEffectId=null;dialog=null;}if((e.ctrlKey||e.metaKey)&&e.key==="z"){e.preventDefault();e.shiftKey?redo():undo()}if((e.ctrlKey||e.metaKey)&&e.key==="s"){e.preventDefault();saveFile()}}}/>
{#key locale}
<div class="app-shell" class:dropping={fileDrop} ondragenter={onFileDragOver} ondragover={onFileDragOver} ondragleave={onFileDragLeave} ondrop={onFileDrop}>
  <header class="topbar">
    <div class="brand"><span class="brand-mark">A</span><div><strong>ArtMaker</strong><small>PRINT CANVAS</small></div></div>
    <nav class="menu-actions"><button onclick={fresh}>{t("new")}</button><button onclick={()=>projectInput.click()}>{t("open")}</button><button onclick={saveFile}>{t("save")}</button><span></span><button onclick={()=>fileInput.click()}>{t("import")}</button><button onclick={openSettings}>{t("settings")}</button><span></span><button onclick={undo} disabled={!history.length}>{t("undo")}</button><button onclick={redo} disabled={!future.length}>{t("redo")}</button></nav>
    <div class="header-end"><span class="autosave">{status||`${doc.spec.dpi} DPI · ${px.width} × ${px.height} px`}</span><button class="icon-btn" onclick={toggleTheme} title={t("theme")}>◐</button><button class="lang-btn" onclick={toggleLocale}>{t("lang")}</button><button class="export-btn" onclick={exportPng}>{t("export")}</button></div>
  </header>
  <div class="workspace">
    <aside class="toolrail">
      {#each tools as item}<button class:active={tool===item.id} onclick={()=>tool=item.id} title={locale==="zh-CN"?item.zh:item.en}><b>{item.icon}</b><small>{locale==="zh-CN"?item.zh:item.en}</small></button>{/each}
    </aside>
    <section class="center">
      <div class="contextbar">{#if tool==="select"}<span class="tool-hint">{t("selectHint")}</span>{:else if tool==="eyedropper"}<span class="tool-hint">{t("eyedropperHint")}</span>{:else}{#if tool!=="eraser"}<label><span>{t("color")}</span><input type="color" bind:value={color}/></label>{/if}{#if tool!=="fill"}<label><span>{t("size")}</span><input class="range" type="range" min="1" max="500" bind:value={size}/><output>{size}px</output></label>{/if}{#if tool==="brush"||tool==="eraser"}<label><span>{t("hardness")}</span><input class="range" type="range" min="0" max="1" step=".01" bind:value={hardness}/><output>{Math.round(hardness*100)}%</output></label>{/if}{/if}</div>
      <div class="canvas-stage" class:panning bind:this={stage} onwheel={wheel} onpointerdown={pointerDown} onpointermove={pointerMove} onpointerup={pointerUp} onpointercancel={pointerUp} onpointerleave={()=>{if(!drawing&&!panning)cursor.visible=false}}><div class="canvas-wrap" style={wrapStyle}><div class="ruler horizontal">{#each [0,.25,.5,.75,1] as ratio}<span style={`left:${ratio*100}%`}>{Math.round(px.width*ratio)}</span>{/each}</div><div class="ruler vertical">{#each [0,.25,.5,.75,1] as ratio}<span style={`top:${ratio*100}%`}>{Math.round(px.height*ratio)}</span>{/each}</div><canvas class:pixelated={zoom>=1&&Number.isInteger(zoom)} bind:this={canvas}></canvas>{#if tool==="select"&&active&&!active.locked}{@const box=contentBox(active)}{#if box}<div class="layer-frame" style={selectFrameStyle(active,box)}><i class="bounds"></i>{#each handles as h}<i class="handle {h}" data-handle={h}></i>{/each}</div>{/if}{/if}<div class="trim-guide" style={`left:${px.trimX*zoom}px;top:${px.trimY*zoom}px;width:${px.trimWidth*zoom}px;height:${px.trimHeight*zoom}px`}><span class="guide-badge">{t("trim")}</span></div><div class="safe-guide" style={`left:${(px.trimX+safePx)*zoom}px;top:${(px.trimY+safePx)*zoom}px;width:${(px.trimWidth-safePx*2)*zoom}px;height:${(px.trimHeight-safePx*2)*zoom}px`}><span class="guide-badge">{t("safeGuide")}</span></div>{#if cursor.visible&&(tool==="brush"||tool==="eraser")}<div class="brush-cursor" style={`left:${cursor.x*zoom}px;top:${cursor.y*zoom}px;width:${Math.max(1,size*zoom)}px;height:${Math.max(1,size*zoom)}px`}></div>{/if}</div><div class="zoom"><button onclick={()=>setZoom(zoomLevels[Math.max(0,zoomLevels.indexOf(zoom)-1)])}>−</button><span>{Math.round(zoom*100)}%</span><button onclick={()=>setZoom(zoomLevels[Math.min(zoomLevels.length-1,zoomLevels.indexOf(zoom)+1)])}>＋</button></div></div>
    </section>
    <aside class="rightbar">
      <section class="panel layer-panel"><div class="panel-title"><b>{t("layers")}</b><div><button onclick={addText}>T</button><button onclick={addLayer}>＋</button></div></div><div class="layer-list">{#each doc.layers as layer (layer.id)}<div class="layer-item" class:selected={layer.id===doc.activeLayerId} class:off={!layer.visible} class:dragging={dragLayerId===layer.id} class:drop-target={dropLayerId===layer.id} draggable="true" onclick={()=>selectLayer(layer.id)} ondragstart={(e)=>onLayerDragStart(e,layer.id)} ondragover={(e)=>onLayerDragOver(e,layer.id)} ondrop={(e)=>onLayerDrop(e,layer.id)} ondragend={onLayerDragEnd}><span class="vis" onclick={(e)=>{e.stopPropagation();toggleLayer(layer)}}></span><span class="thumb">{layer.type==="image"?"▧":layer.type==="text"?"T":"✦"}</span><span class="layer-name">{layer.name}<small>{layer.linkSourceId?`${t("link")} · ${layerName(layer.linkSourceId)}`:`${layer.type.toUpperCase()} · ${Math.round(layer.opacity*100)}%`}</small></span></div>{/each}</div>{#if active}<div class="layer-props"><label>{t("name")} <input class="layer-name-input" type="text" bind:value={active.name} oninput={()=>{doc={...doc,layers:[...doc.layers]};queueSave()}}/></label><label>{t("opacity")} <input type="range" min="0" max="1" step=".01" bind:value={active.opacity} oninput={()=>{renderDocument();queueSave()}}/></label><label>{t("blend")} <select bind:value={active.blendMode} onchange={()=>{renderDocument();queueSave()}}><option value="normal">Normal</option><option value="multiply">Multiply</option><option value="screen">Screen</option><option value="overlay">Overlay</option></select></label><div class="transform-fields"><label>X <input type="number" bind:value={active.transform.x} oninput={()=>{renderDocument();queueSave()}}/></label><label>Y <input type="number" bind:value={active.transform.y} oninput={()=>{renderDocument();queueSave()}}/></label><label>{t("scaleX")} <input type="number" min="1" value={Math.round(active.transform.scaleX*100)} oninput={(e)=>setLayerScale("scaleX",e)}/></label><label>{t("scaleY")} <input type="number" min="1" value={Math.round(active.transform.scaleY*100)} oninput={(e)=>setLayerScale("scaleY",e)}/></label></div><label>{t("link")} <select value={active.linkSourceId??""} onchange={onLinkChange}><option value="">{t("linkNone")}</option>{#each linkSources as source}<option value={source.id}>{source.name}</option>{/each}</select></label><div><button onclick={()=>replaceInput.click()}>{t("replace")}</button></div><div><button onclick={duplicateLayer}>{t("duplicate")}</button><button class="danger" onclick={askRemoveLayer}>{t("remove")}</button></div></div>{/if}</section>
      <section class="panel effects-panel"><div class="panel-title"><b>{t("effects")}</b><button onclick={()=>showEffects=!showEffects}>＋</button></div>{#if showEffects}<div class="effect-picker">{#each effectRegistry as effect}<button onclick={()=>{addEffect(effect.type);showEffects=false}}>{effect.label[locale]}</button>{/each}</div>{/if}{#if active?.effects.length}<div class="effect-list">{#each active.effects as effect,index (effect.id)}<div class="effect-item"><div><input type="checkbox" bind:checked={effect.enabled} onchange={applyEffects}/><b>{effectRegistry.find(x=>x.type===effect.type)?.label[locale]}</b><span><button onclick={()=>moveEffect(index,-1)}>↑</button><button onclick={()=>moveEffect(index,1)}>↓</button><button onclick={()=>removeEffect(index)}>×</button></span></div>{#each Object.entries(effect.params).slice(0,8) as [key,value]}{#if effect.type==="halftone"&&(key==="linkSpacing"||key==="spacingY")}{:else if effect.type==="halftone"&&key==="spacingX"}<div class="spacing-link"><label>spacingX<input type="number" min="1" step="1" value={Number(effect.params.spacingX)} onchange={(e)=>setEffectParam(effect,"spacingX",e)}/></label><button class:active={Boolean(effect.params.linkSpacing)} onclick={()=>toggleHalftoneLink(effect)} title={t("linkSpacing")}>↔</button><label>spacingY<input type="number" min="1" step="1" disabled={Boolean(effect.params.linkSpacing)} value={Number(effect.params.spacingY)} onchange={(e)=>setEffectParam(effect,"spacingY",e)}/></label></div>{:else}<label>{key}{#if typeof value==="boolean"}<input type="checkbox" checked={Boolean(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{:else if key==="sourceColor"}<span class="source-picker"><input type="color" value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}/><button class:active={pickingEffectId===effect.id} onclick={()=>pickingEffectId=pickingEffectId===effect.id?null:effect.id} title={t("pickColor")}>◉</button></span>{:else if /color/i.test(key)||key==="from"||key==="to"}<input type="color" value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{:else if key==="direction"}<select value={String(value)} onchange={(e)=>setEffectParam(effect,key,e)}><option value="horizontal">→</option><option value="vertical">↓</option><option value="diagonal-down">↘</option><option value="diagonal-up">↗</option></select>{:else if key==="strength"}<span class="effect-range"><input type="range" min="0" max="1" step=".01" value={Number(value)} oninput={(e)=>setEffectParam(effect,key,e)}/><output>{Math.round(Number(value)*100)}%</output></span>{:else if key==="lightness"}<span class="effect-range"><input type="range" min="-100" max="100" step="1" value={Number(value)} oninput={(e)=>setEffectParam(effect,key,e)}/><output>{Number(value)>0?"+":""}{Math.round(Number(value))}</output></span>{:else}<input type="number" min={key==="dot"||key.startsWith("spacing")?1:0} max={key==="tolerance"||key==="softness"?100:undefined} step="1" value={Number(value)} onchange={(e)=>setEffectParam(effect,key,e)}/>{/if}</label>{/if}{/each}</div>{/each}</div>{:else}<p class="empty-effects">{t("empty")}</p>{/if}</section>
    </aside>
  </div>
</div>
{#if showSettings}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)cancelSettings()}}><section class="settings-modal" role="dialog" aria-modal="true" aria-label={t("settings")}><div class="panel-title"><b>{t("settings")}</b><button onclick={cancelSettings}>×</button></div><div class="field-grid"><label>{t("width")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.width}/></label><label>{t("height")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.height}/></label><label>{t("dpi")}<input type="number" min="72" max="2400" bind:value={doc.spec.dpi}/></label><label>{t("unit")}<select bind:value={doc.spec.unit}><option value="mm">mm</option><option value="inch">inch</option></select></label></div><div class="wide-field">{t("bleed")} ({doc.spec.unit})<div class="bleed-row">{#each bleedSides as side}<label>{t(side.key)}<input aria-label={t(side.key)} type="number" value={doc.spec.bleed[side.id]} onchange={(e)=>{doc.spec.bleed[side.id]=Number(e.currentTarget.value);doc={...doc}}}/></label>{/each}</div></div><label class="wide-field">{t("safe")} ({doc.spec.unit})<input type="number" bind:value={doc.spec.safeMargin}/></label><div class="pixel-card"><small>{t("pixel")}</small><strong>{px.width.toLocaleString()} × {px.height.toLocaleString()} px</strong><span>≈ {Math.round(px.width*px.height*4/1024/1024)} MB RGBA</span></div><footer><button onclick={cancelSettings}>{t("cancel")}</button><button class="apply" onclick={async()=>{await updateSpec();settingsOriginal=null;showSettings=false}}>{t("apply")}</button></footer></section></div>{/if}
{#if dialog}<div class="modal-backdrop" role="presentation" onclick={(e)=>{if(e.target===e.currentTarget)dialog=null}}><section class="settings-modal confirm-modal" role="dialog" aria-modal="true" aria-label={dialog.title}><div class="panel-title"><b>{dialog.title}</b><button onclick={()=>dialog=null}>×</button></div><p class="confirm-copy">{dialog.message}</p><footer><button onclick={()=>dialog=null}>{t("cancel")}</button><button class={dialog.danger?"danger":"apply"} onclick={()=>{const action=dialog!.onConfirm;dialog=null;action();}}>{t("confirm")}</button></footer></section></div>{/if}
<input class="hidden" bind:this={fileInput} type="file" accept="image/png,image/jpeg,image/webp" onchange={importImage}/><input class="hidden" bind:this={replaceInput} type="file" accept="image/png,image/jpeg,image/webp" onchange={onReplaceImage}/><input class="hidden" bind:this={projectInput} type="file" accept=".artmaker" onchange={openProject}/>
{/key}
